(352, 'Zverejnenie malej nápovedy 2. kola letnej časti Suši', '[\"other\"]', 'seminar', '{\"start\":\"2022-05-02\"}', 'https://susi.trojsten.sk/', '[\"online\"]', '{\"min\":\"ss1\",\"max\":null}', 'Týždeň pred koncom kola sa na stránke zverejní prvá sada \"malých\" nápovied ku jednotlivým šifrám. Po tomto čase sa dajú riešenia odovzdávať iba za 4 body.', NULL, 0, 0, NULL),
