(419, 'Klub Trojstenu', '[\"mat\",\"fyz\",\"inf\"]', 'vikendovka', '{\"start\":\"2022-12-16\",\"end\":\"2022-12-17\"}', 'https://klub.trojsten.sk/', '[\"Bratislava\"]', '{\"min\":\"ss1\",\"max\":\"ss4\"}', 'Klub je poloformálna, polooficálna akcia, koná sa po väčších akciách Trojstenu, snažíme sa utužiť kolektív riešiteľov a popri tom pribrať nových ľudí do našej partie. Neváhaj a pripoj sa k nám (agitačné reči – „Come to the dark side - we have cookies!“).', NULL, 0, 0, NULL),
(420, 'Letná škola matematiky', '[\"mat\"]', 'prednasky', '{\"start\":\"2023-07-17\",\"end\":\"2023-07-28\"}', 'https://leto.trojsten.sk/', '[\"Bratislava\"]', '{\"min\":\"ss1\",\"max\":\"ss4\"}', NULL, NULL, 0, 0, NULL),
(421, 'Akadémia Trojstenu', '[\"mat\",\"fyz\",\"inf\"]', 'prednasky', '{\"start\":\"2022-12-16\"}', 'https://akademia.trojsten.sk/', '[\"Bratislava\"]', '{\"min\":\"ss1\",\"max\":\"ss4\"}', 'Každoročne Ťa čaká 6 prednášok, v ktorých populárnym a pochopiteľným spôsobom naši prednášajúci priblížia zaujímavé oblasti zo svojich vedných disciplín. Akadémia je určená všetkým vzdelania a zábavy chtivým poslucháčom.', 'red', 0, 0, NULL),
(422, 'Klub Trojstenu', '[\"mat\",\"fyz\",\"inf\"]', 'vikendovka', '{\"start\":\"2022-11-04\",\"end\":\"2022-11-05\"}', 'https://klub.trojsten.sk/', '[\"Bratislava\"]', '{\"min\":\"ss1\",\"max\":\"ss4\"}', 'Klub je poloformálna, polooficálna akcia, koná sa po väčších akciách Trojstenu, snažíme sa utužiť kolektív riešiteľov a popri tom pribrať nových ľudí do našej partie. Neváhaj a pripoj sa k nám (agitačné reči – „Come to the dark side - we have cookies!“).', NULL, 0, 0, NULL),
