(599, 'Prázninová šifrovačka Trojstenu', '[\"other\"]', 'sutaz', '{\"start\":\"2023-07-15\",\"text\":\"Druhý ročník PŠT, ktorá je súčasťou voľnočasového programu Letnej školy Trojstenu. Je zameraná hlavne na stredoškolákov, aj začiatočníkov, no na svoje si vedia prísť aj skúsenejšie, nie nutne stredoškolské tímy.\"}', 'https://susi.trojsten.sk/pst/', '[\"Bratislava\"]', '{\"min\":\"ss1\",\"max\":\"ss4\"}', NULL, NULL, 0, 0, NULL),
(600, 'Letná škola fyziky', '[\"fyz\"]', 'prednasky', '{\"start\":\"2024-07-22\",\"end\":\"2024-08-02\"}', 'https://leto.trojsten.sk/', '[\"Bratislava\"]', '{\"min\":\"ss1\",\"max\":\"ss4\"}', NULL, NULL, 0, 0, NULL),
(601, 'Klub Trojstenu', '[\"mat\",\"fyz\",\"inf\"]', 'vikendovka', '{\"start\":\"2023-11-03\",\"end\":\"2023-11-04\"}', 'https://forms.gle/sWm5snGCwu3MGw1X9', '[\"Bratislava\"]', '{\"min\":\"ss1\",\"max\":\"ss4\"}', 'Klub je poloformálna, polooficálna akcia, koná sa po väčších akciách Trojstenu, snažíme sa utužiť kolektív riešiteľov a popri tom pribrať nových ľudí do našej partie. Neváhaj a pripoj sa k nám (agitačné reči – „Come to the dark side - we have cookies!“).', NULL, 0, 0, NULL),
(602, 'Akadémia Trojstenu', '[\"mat\",\"fyz\",\"inf\"]', 'prednasky', '{\"start\":\"2023-12-15\"}', 'https://akademia.trojsten.sk/', '[\"Bratislava\"]', '{\"min\":\"ss1\",\"max\":\"ss4\"}', 'Každoročne Ťa čaká 6 prednášok, v ktorých populárnym a pochopiteľným spôsobom naši prednášajúci priblížia zaujímavé oblasti zo svojich vedných disciplín. Akadémia je určená všetkým vzdelania a zábavy chtivým poslucháčom.', 'red', 0, 0, NULL),
(603, 'Letná škola programovania', '[\"inf\"]', 'prednasky', '{\"start\":\"2024-07-08\",\"end\":\"2024-07-19\"}', 'https://leto.trojsten.sk/', '[\"Bratislava\"]', '{\"min\":\"zs7\",\"max\":\"ss4\"}', NULL, NULL, 0, 0, NULL),
(604, 'Letná škola matematiky', '[\"mat\"]', 'prednasky', '{\"start\":\"2024-07-15\",\"end\":\"2024-07-26\"}', 'https://leto.trojsten.sk/', '[\"Bratislava\"]', '{\"min\":\"ss1\",\"max\":\"ss4\"}', NULL, NULL, 0, 0, NULL),
(605, 'Klub Trojstenu', '[\"mat\",\"fyz\",\"inf\"]', 'vikendovka', '{\"start\":\"2024-04-19\",\"end\":\"2024-04-20\"}', 'https://klub.trojsten.sk/', '[\"Bratislava\"]', '{\"min\":\"ss1\",\"max\":\"ss4\"}', 'Klub je poloformálna, polooficálna akcia, koná sa po väčších akciách Trojstenu, snažíme sa utužiť kolektív riešiteľov a popri tom pribrať nových ľudí do našej partie. Neváhaj a pripoj sa k nám (agitačné reči – „Come to the dark side - we have cookies!“).', NULL, 0, 0, NULL),
