INSERT INTO `organizer` (`id`, `name`, `icon`, `logo`, `web`, `type`, `info`, `color`, `country`) VALUES
(1, 'Nivam', 'logos/nivam.svg', NULL, 'https://nivam.sk', 'statna', '', NULL, 'sk'),
(2, 'ŠIOV', 'logos/siov.svg', NULL, 'https://siov.sk', 'statna', '', NULL, 'sk'),
(3, 'Metalympiáda', 'logos/metalympiada.svg', NULL, 'https://metalympiada.org/', 'other', '', '#118282', 'sk'),
(4, 'SOVVA', 'logos/sovva.svg', NULL, 'https://sovva.sk', 'oz', '', NULL, 'sk'),
(5, 'Talentída', 'logos/talentida.svg', NULL, 'https://talentida.sk', 'no', '', NULL, 'sk'),
(6, 'ŠpMNDaG', 'logos/spmndag.svg', NULL, 'https://spmndag.sk', 'skola', '', NULL, 'sk'),
(7, 'SSE', 'logos/sse.svg', NULL, 'https://skse.sk', 'oz', '', NULL, 'sk'),
(8, 'Gymnázium Veľká okružná Žilina', 'logos/gvoza.svg', NULL, 'https://gvoza.sk', 'skola', '', NULL, 'sk'),
(9, 'FYKOS', 'logos/fykos.svg', NULL, 'https://fykos.cz', 'other', '', NULL, 'cz'),
(10, 'Kybersoutěž', 'logos/kybersoutez.png', NULL, 'https://kybersoutez.cz/', 'other', '', '#feed01', 'cz'),
(11, 'Kasiopea', 'logos/kasiopea.svg', NULL, 'https://kasiopea.matfyz.cz/', 'other', '', '#331c47', 'cz'),
(12, 'Iuventa', 'logos/iuventa.svg', NULL, 'https://iuventa.sk', 'statna', '', NULL, 'sk'),
(13, 'Astronomická olympiáda', 'logos/ao.svg', NULL, 'https://aosk.sk', 'statna', 'Astronomická olympiáda je vedomostná súťaž pre študentov základných a stredných škôl. Jej cieľom je vzdelávanie v oblasti astronómie a astrofyziky, a výber reprezentantov na Medzinárodnú olympiádu z astronómie a astrofyziky (IOAA).', '#b28500', 'sk'),
(14, 'Prírodovedecká fakulta Univerzity Komenského v Bratislave', 'logos/prifuk.png', NULL, 'https://fns.uniba.sk/', 'skola', '', NULL, 'sk'),
(15, 'KSP - Korespondenční Seminář z Programování', 'logos/ksp-praha.svg', NULL, 'https://ksp.mff.cuni.cz/', 'other', '', '#000', 'cz'),
(16, 'MaSo', 'logos/maso.svg', NULL, 'https://maso.mff.cuni.cz/', 'oz', 'MaSo je týmová matematická soutěž pro žáky šestých až devátých tříd základních škol a odpovídajících ročníků víceletých gymnázií, která se koná dvakrát ročně. Nejde tu ovšem jen o počítání příkladů. Za spočítané příklady získávají týmy tahy do hry, která je pak hlavním zdrojem jejich bodů do celkového hodnocení. Hra je každý rok jiná. Týmy, které se již účastnily, tedy nemají výhodu její znalosti.', '#ffd842', 'cz'),
(17, 'FMFI UK', 'logos/matfyz.svg', NULL, 'https://fmph.uniba.sk', 'skola', '', NULL, 'sk'),
(18, 'Trojsten', 'logos/trojsten.svg', NULL, 'https://trojsten.sk', 'oz', 'Trojsten je občianske združenie, ktoré na Slovensku organizuje aktivity v matematike, fyzike a informatike pre študentov základných, no najmä stredných škôl. Časť aktivít, súťaže Náboj sa podarilo úspešne expandovať za hranice Slovenska do ďalších jedenástich krajín a v súčastnosti sa ich zúčastňuje každý rok niekoľko tisíc účastníkov.', '#1077C1', 'sk'),
(19, 'Riešky', 'logos/riesky.svg', NULL, 'https://riesky.sk', 'oz', 'Riešky sú korešpondenčný seminár pre žiakov 5. - 9. ročníka základných škôl a príslušných ročníkov gymnázií. Najúspešnejších riešiteľov čaká týždňové sústredenie plné zaujímavej matematiky, netradičných hier a množstvom zábavy. Okrem toho organizujú aj denný tábor v Bratislave, ktorý je ochutnávkou toho, čo na sústredení môžete zažiť.', '#000000', 'sk'),
(20, 'PraSe', 'logos/prase.svg', 'logos/prase.svg', 'https://prase.cz/', 'other', '', 'blue', 'cz'),
(21, 'GJH', 'logos/gjh.svg', NULL, 'https://gjh.sk', 'skola', '', NULL, 'sk'),
(22, 'SEZAM', 'logos/sezam.svg', NULL, 'https://sezam.sk', 'other', 'SEZAM sa venuje organizácii korešpondenčných seminárov SEZAM a SEZAMKO pre žiakov od 5. po 9. ročník základných škôl a príslušných ročníkov gymnázií. Pre najúspešnejších riešiteľov organizuje stretnutia v zime aj v lete. Na týchto stretnutiach sa venujú matematike, športu, rôznym hrám, hlavolamom a iným zaujímavým aktivitám.', '#09BAE7', 'sk'),
(23, 'eduB', 'logos/edub.svg', NULL, 'https://edub.sk', 'oz', '', NULL, 'sk'),
(24, 'P-mat', 'logos/p-mat.svg', NULL, 'https://p-mat.sk', 'no', 'Nezisková organizácia P-Mat prostredníctvom matematiky, fyziky, hier a netradičných zážitkov vytvára dostupné, priateľské a podnetné prostredie pre zvedavé deti a rozvíja tak ich logické a kritické myslenie, schopnosť riešiť problémy, sociálne zručnosti a morálne cítenie. Okrem korešpondenčnej časti a sústredení organizuje aj pobytové víkendové akcie, jednodňové súťaže nie len offline, ale aj online najmä pre základné školy a príslušné ročníky gymnázií.', '#F68712', 'sk'),
(25, 'STROM', 'logos/strom.svg', NULL, 'https://strom.sk', 'oz', 'Združenie STROM sa už dlhé roky úspešne venuje tomu, aby sa v mysliach mladých ľudí otázka: “Na čo mi to bude?” neobjavovala ako súčasť výhovoriek, prečo sa počítaniu úloh alebo logickým úvahám nevenovať, ale ako podnet k tomu, aby sa pokúsili vedieť viac a posúvali ďalej svoje možnosti. Okrem korešpondenčnej časti a sústredení sa venuje organizácii školských minisústredení, výletov a jednodňových súťaží v Košiciach.', '#000000', 'sk'),
(26, 'NÚCEM', 'logos/nucem.svg', NULL, 'https://nucem.sk', 'statna', '', NULL, 'sk');
